/**
 * Datenbank – Customer Dashboard
 * Supabase als einzige Datenbank (Postgres, Auth, Storage, Realtime)
 */

export { supabase } from './supabase'

/** Verbindung beim Serverstart testen */
export async function initDatabase(): Promise<void> {
  const { supabase } = await import('./supabase')
  // Einfacher Verbindungstest via Supabase Auth (braucht keine Tabelle)
  const { error } = await supabase.auth.getSession()
  if (error) {
    throw new Error(`Supabase Verbindung fehlgeschlagen: ${error.message}`)
  }
  console.log('✓ Supabase Verbindung erfolgreich')
}
